572	   157	    /// The tenant's webhook subscriptions.
573	   158	    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
574	   159	        let mut subscriptions = Vec::new();
575	   160	        let mut cursor: Option<String> = None;
576	   161	        loop {
577	   162	            let page = self.settings.query(tenant, cursor.as_deref()).await;
578	   163	            subscriptions.extend(page.items.iter().filter(|s| s.kind == WEBHOOK_KIND).filter_map(Subscription::from_setting));
579	   164	            match page.next {
580	   165	                Some(next) => cursor = Some(next),
