586	   171	    /// POSTs `body` to `sub` and reports the outcome; `true` if delivered.
587	   172	    async fn dispatch(&self, tenant: &str, sub: &Subscription, body: &[u8]) -> bool {
588	   173	        let outcome = match self.transport.post(&sub.url, body).await {
589	   174	            Ok(status) if (200..300).contains(&status) => Outcome::Delivered { status },
590	   175	            Ok(status) => Outcome::Failed { reason: format!("HTTP {status}") },
591	   176	            Err(error) => Outcome::Failed { reason: error.to_string() },
592	   177	        };
